import type { CapturedNetworkRequest } from "posthog-js";
import { describe, expect, it, vi } from "vitest";
import {
	createReplayGate,
	isReplayPath,
	maskNetworkRequest,
	pathnameOf,
} from "@/lib/replay-gate";

describe("isReplayPath", () => {
	it.each([
		"/docs/reference/skills/implement",
		"/docs/reference/hooks/pretool",
		"/docs/reference/agents/ci-cd-engineer",
		"/docs/reference/",
	])("allows %s", (p) => {
		expect(isReplayPath(p)).toBe(true);
	});

	it.each([
		"/",
		"/docs",
		"/docs/reference",
		"/docs/referencex/skills",
		"/docs/foundations/overview",
		"/lab/anything",
		"/Docs/reference/skills/implement",
		"/api/search",
	])("refuses %s", (p) => {
		expect(isReplayPath(p)).toBe(false);
	});
});

describe("pathnameOf", () => {
	const base = "https://orchestkit.yonyon.ai/docs/foundations/overview";

	it("resolves relative and absolute hrefs, dropping query and hash", () => {
		expect(pathnameOf("/docs/reference/skills/x?q=1#h", base)).toBe(
			"/docs/reference/skills/x",
		);
		expect(
			pathnameOf("https://orchestkit.yonyon.ai/docs/reference/hooks/y", base),
		).toBe("/docs/reference/hooks/y");
	});

	it("normalises dot segments so they cannot smuggle a non-reference path in", () => {
		expect(pathnameOf("/docs/reference/../foundations/overview", base)).toBe(
			"/docs/foundations/overview",
		);
	});
});

describe("createReplayGate", () => {
	const make = () => {
		const controls = {
			startSessionRecording: vi.fn(),
			stopSessionRecording: vi.fn(),
		};
		return { controls, gate: createReplayGate(controls) };
	};

	it("never starts on a non-reference path", () => {
		const { controls, gate } = make();
		gate.sync("/");
		gate.sync("/docs/foundations/overview");
		expect(controls.startSessionRecording).not.toHaveBeenCalled();
		expect(controls.stopSessionRecording).not.toHaveBeenCalled();
	});

	it("starts once on a reference path and stays started across reference navigations", () => {
		const { controls, gate } = make();
		gate.sync("/docs/reference/skills/a");
		gate.sync("/docs/reference/hooks/b");
		expect(controls.startSessionRecording).toHaveBeenCalledTimes(1);
		expect(controls.startSessionRecording).toHaveBeenCalledWith();
		expect(controls.stopSessionRecording).not.toHaveBeenCalled();
	});

	it("stops when leaving the reference tree and restarts on return", () => {
		const { controls, gate } = make();
		gate.sync("/docs/reference/skills/a");
		gate.sync("/");
		expect(controls.stopSessionRecording).toHaveBeenCalledTimes(1);
		gate.sync("/docs/reference/skills/a");
		expect(controls.startSessionRecording).toHaveBeenCalledTimes(2);
	});

	it("stop() is owed even if the SDK has not actually begun recording", () => {
		const { controls, gate } = make();
		gate.sync("/docs/reference/skills/a");
		gate.stop();
		gate.stop();
		expect(controls.stopSessionRecording).toHaveBeenCalledTimes(1);
	});
});

describe("maskNetworkRequest", () => {
	it("drops headers and bodies and strips query and hash from the URL", () => {
		const req = {
			name: "https://orchestkit.yonyon.ai/api/search?query=secret+term#frag",
			entryType: "resource",
			startTime: 1,
			duration: 2,
			method: "GET",
			status: 200,
			requestHeaders: { accept: "application/json" },
			requestBody: '{"q":"secret"}',
			responseHeaders: { "content-type": "application/json" },
			responseBody: '[{"title":"secret"}]',
		} as CapturedNetworkRequest;

		const masked = maskNetworkRequest(req);

		expect(masked.name).toBe("https://orchestkit.yonyon.ai/api/search");
		expect(masked.requestHeaders).toBeUndefined();
		expect(masked.requestBody).toBeNull();
		expect(masked.responseHeaders).toBeUndefined();
		expect(masked.responseBody).toBeNull();
		expect(JSON.stringify(masked)).not.toContain("secret");
		expect(masked.status).toBe(200);
	});

	it("leaves a URL without query or hash unchanged", () => {
		const masked = maskNetworkRequest({
			name: "/ingest/flags/",
		} as CapturedNetworkRequest);
		expect(masked.name).toBe("/ingest/flags/");
	});
});
